document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('[data-branch-color]').forEach(function(el){el.style.setProperty('--branch-color',el.getAttribute('data-branch-color')||'#94a3b8');var bg=el.getAttribute('data-branch-bg');if(bg){el.style.setProperty('--branch-bg',bg);}});document.querySelectorAll('[data-dot-color]').forEach(function(el){el.style.background=el.getAttribute('data-dot-color')||'#94a3b8';});});